<script setup lang="ts">
import {ref} from "vue";import {onShow} from "@dcloudio/uni-app";import {clear,request} from "../../api";const me=ref<any>(),space=ref<any>();async function load(){try{me.value=await request("/api/v1/auth/me");space.value=await request("/api/v1/spaces/current")}catch{}}async function invite(){space.value=await request("/api/v1/spaces/invite","POST");uni.setClipboardData({data:space.value.invite_code})}function logout(){clear();uni.redirectTo({url:"/pages/login/login"})}onShow(load);
</script>
<template><view class="page"><view class="card"><text class="name">{{space?.name}}</text><text>我是 {{me?.nickname}}</text><view><text v-for="m in space?.members" :key="m.user_id" class="chip">{{m.nickname}}</text></view></view><view class="card"><text>邀请另一半</text><text class="code">{{space?.invite_code||'点击生成'}}</text><button @click="invite">复制邀请码</button></view><button class="logout" @click="logout">退出登录</button></view></template>
<style scoped>.page{padding:34rpx}.card{background:white;padding:32rpx;border-radius:24rpx;margin-bottom:24rpx}.name{display:block;font-size:40rpx;font-weight:700;margin-bottom:16rpx}.chip{display:inline-block;background:#fff0ee;color:#c45c6a;padding:8rpx 18rpx;border-radius:999rpx;margin:20rpx 12rpx 0 0}.code{display:block;font-size:48rpx;letter-spacing:8rpx;color:#c45c6a;margin:20rpx 0}button{background:#c45c6a;color:white}.logout{background:white;color:#c45c6a}</style>

